  const int64_t sWc = (int64_t)KH * KW;
  const int64_t sWh = (int64_t)KW;
  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYo = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, C, H, Win),
      make_stride(sXn, sXc, sXh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, C, KH, KW),
      make_stride(sWo, sWc, sWh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, OC, Hout, Wout),
      make_stride(sYn, sYo, sYh, Int<1>{})
  );
  auto sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_layout(
          make_shape(Int<C_CHUNK>{}, ih_tile, iw_tile),
          make_stride((int64_t)ih_tile * iw_tile, (int64_t)iw_tile, Int<1>{})
