  // The cp.async copy for channel chunk k+1 is issued before computing chunk
  // k, so global-memory latency overlaps with the FMA loop instead of
  // serializing between the load phase and the compute phase. Out-of-bounds
  // elements use cp.async zero-fill (src-size = 0), which preserves the exact
  // padding semantics of the original guarded scalar loads.
  auto load_tile = [&](int c0, int buf) {
    float* sbase = sX_ptr + (size_t)buf * buf_elems;
    for (int idx = tid; idx < x_elems; idx += Threads) {
      const int cc = idx / tile_hw;
      const int rem = idx - cc * tile_hw;
      const int th = rem / iw_tile;
      const int tw = rem - th * iw_tile;
