      load_tile(next_c0, buf ^ 1);
      cp_async_wait_group<1>();
    } else {
      cp_async_wait_group<0>();
    }
    __syncthreads();
    auto sXb = make_tensor(
        make_smem_ptr(sX_ptr + (size_t)buf * buf_elems),
        make_layout(
            make_shape(Int<C_CHUNK>{}, ih_tile, iw_tile),
            make_stride((int64_t)tile_hw, (int64_t)iw_tile, Int<1>{})
