            for (int co = 0; co < OC_TILE; ++co) {
              const float wv = (c_ok && (oc0 + co < OC)) ? __ldg(w_c + (int64_t)co * sWo) : 0.0f;
              #pragma unroll
              for (int j = 0; j < OW_BLOCK; ++j) {
                acc[j][co] += xv[j] * wv;
              }
            }
          }
        }
      }
    }
    __syncthreads();
    buf ^= 1;
  }
  if (row_valid) {
    #pragma unroll
    for (int j = 0; j < OW_BLOCK; ++j) {
      if (out_valid[j]) {
        #pragma unroll
        for (int co = 0; co < OC_TILE; ++co) {
          const int oc = oc0 + co;
          if (oc < OC) {
            const float bias = (B != nullptr) ? B[oc] : 0.0f;
            mY(n, oc, oh, ow[j]) = acc[j][co] + bias;
          }
        }
      }
    }
  }
}

torch::Tensor conv2d_forward_cute(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride,
                                  int pad_h,
                                  int pad_w,
                                  int dil_h,
                                  int dil_w)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors.");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32.");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W].");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, KH, KW].");
  TORCH_CHECK(stride > 0 && dil_h > 0 && dil_w > 0, "stride/dilation must be positive.");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be non-negative.");

  const at::cuda::CUDAGuard device_guard(x.device());

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N = x_c.size(0);
  const int64_t C = x_c.size(1);
  const int64_t H = x_c.size(2);
  const int64_t Win = x_c.size(3);

  const int64_t OC = w_c.size(0);
  const int64_t WC = w_c.size(1);
  const int64_t KH = w_c.size(2);
  const int64_t KW = w_c.size(3);
  TORCH_CHECK(WC == C, "w.size(1) must equal x.size(1).");

  const int64_t Hout = (H + 2LL * pad_h - (int64_t)dil_h * (KH - 1) - 1) / stride + 1;
  const int64_t Wout = (Win + 2LL * pad_w - (int64_t)dil_w * (KW - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid convolution output size.");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32.");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC].");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x_c.options());

  constexpr int OC_TILE = 16;
  constexpr int C_CHUNK = 8;
  constexpr int OH_TILE = 16;
  constexpr int OW_TILE = 16;
  constexpr int OW_BLOCK = 2;
  constexpr int Threads = OH_TILE * OW_TILE;

  const int ih_tile = (OH_TILE - 1) * stride + dil_h * (int)(KH - 1) + 1;
  const int iw_tile = (OW_TILE * OW_BLOCK - 1) * stride + dil_w * (int)(KW - 1) + 1;

  const size_t smem_bytes =
      2ULL * (size_t)C_CHUNK * ih_tile * iw_tile * sizeof(float);

  const int num_oc_tiles = (int)((OC + OC_TILE - 1) / OC_TILE);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((Wout + OW_TILE * OW_BLOCK - 1) / (OW_TILE * OW_BLOCK)),
      (unsigned)((Hout + OH_TILE - 1) / OH_TILE),
      (unsigned)(N * num_oc_tiles)
  );

  auto kernel = conv2d_direct_cute_kernel<OC_TILE, C_CHUNK, OH_TILE, OW_TILE, OW_BLOCK>;
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_bytes);
  }

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)OC, (int)KH, (int)KW,
      (int)Hout, (int)Wout,
      stride, pad_h, pad_w, dil_h, dil_w,
      num_oc_tiles
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_direct_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
